country_event = {
	id = cyber.1570
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		any_spynetwork = {
			owner = {
				is_same_value = root
			}
			has_modifier = clear_thought_clinic_modifier
			target = {
				any_owned_planet = {
					NOT = {
						has_holding = {
							holding = building_clear_thought_clinic
							owner = root
						}
					}
				}
			}
		}
	}

	immediate = {
		every_spynetwork = {
			limit = {
				owner = {
					is_same_value = root
				}
				has_modifier = clear_thought_clinic_modifier
			}
			if = {
				limit = {
					target = {
						any_owned_planet = {
							has_holding = {
								holding = building_clear_thought_clinic
								owner = root
							}
						}
					}
				}
				# Do nothing
			}
			else = {
				remove_modifier = clear_thought_clinic_modifier
			}
		}
	}
}
